import React, { useState, useEffect } from 'react';
import io from 'socket.io-client';
import './Dashboard.css';

const socket = io('http://localhost:3001');

const Dashboard = () => {
    const [results, setResults] = useState({
        participants: [],
        juries: [],
        teams: [],
        scoreEntries: []
    });

    useEffect(() => {
        const loadResults = async () => {
            try {
                const response = await fetch('http://localhost:3001/api/results');
                const data = await response.json();
                setResults({
                    participants: Array.isArray(data.participants) ? data.participants : [],
                    juries: Array.isArray(data.juries) ? data.juries : [],
                    teams: Array.isArray(data.teams) ? data.teams : [],
                    scoreEntries: Array.isArray(data.scoreEntries) ? data.scoreEntries : []
                });
            } catch (error) {
                console.error('Failed to load dashboard results:', error);
                setResults({ participants: [], juries: [], teams: [], scoreEntries: [] });
            }
        };

        loadResults();

        socket.on('updateResults', (data) => {
            setResults({
                participants: Array.isArray(data.participants) ? data.participants : [],
                juries: Array.isArray(data.juries) ? data.juries : [],
                teams: Array.isArray(data.teams) ? data.teams : [],
                scoreEntries: Array.isArray(data.scoreEntries) ? data.scoreEntries : []
            });
        });

        return () => {
            socket.off('updateResults');
        };
    }, []);

    const getScoreColor = (score) => {
        if (score >= 50) return 'green';
        if (score >= 45) return 'orange';
        return 'red';
    };

    const bestParticipant = results.participants.length > 0 ? results.participants[0] : null;

    return (
        <div className="dashboard-container">
            <h1>Dashboard des Résultats</h1>

            {bestParticipant && (
                <div className="best-participant-card">
                    <h2>🌟 Meilleur Participant 🌟</h2>
                    <h3>{bestParticipant.name}</h3>
                    <p>Score: {bestParticipant.score.toFixed(2)} / 68</p>
                    <p>Niveau: Très bon niveau</p>
                </div>
            )}

            <div className="results-section">
                <h2>Notes par Jury</h2>
                <table className="results-table">
                    <thead>
                        <tr>
                            <th>Jury</th>
                            <th>Nombre de notes</th>
                            <th>Score moyen</th>
                            <th>Score total</th>
                        </tr>
                    </thead>
                    <tbody>
                        {results.juries.map((jury) => (
                            <tr key={jury.name}>
                                <td>{jury.name}</td>
                                <td>{jury.scoreCount}</td>
                                <td>{jury.averageScore.toFixed(2)}</td>
                                <td>{jury.totalScore.toFixed(2)}</td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>

            <div className="results-section">
                <h2>Classement par Participant</h2>
                <table className="results-table">
                    <thead>
                        <tr>
                            <th>Rang</th>
                            <th>Nom</th>
                            <th>Équipe</th>
                            <th>Score</th>
                            <th>Statut</th>
                        </tr>
                    </thead>
                    <tbody>
                        {results.participants.map((p, index) => (
                            <tr key={`${p.name}-${p.team}`} style={{ color: getScoreColor(p.score) }}>
                                <td>{index + 1}</td>
                                <td>{p.name}</td>
                                <td>{p.team}</td>
                                <td>{p.score.toFixed(2)}</td>
                                <td>{p.score >= 50 ? 'VALIDÉ' : 'NON VALIDÉ'}</td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>

            <div className="results-section">
                <h2>Classement par Équipe</h2>
                <table className="results-table">
                    <thead>
                        <tr>
                            <th>Rang</th>
                            <th>Équipe</th>
                            <th>Score Moyen</th>
                        </tr>
                    </thead>
                    <tbody>
                        {results.teams.map((t, index) => (
                            <tr key={t.name}>
                                <td>{index + 1}</td>
                                <td>{t.name}</td>
                                <td>{t.averageScore.toFixed(2)}</td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>

            <div className="results-section">
                <h2>Détail des notes</h2>
                <table className="results-table">
                    <thead>
                        <tr>
                            <th>Jury</th>
                            <th>Équipe</th>
                            <th>Participant</th>
                            <th>Section</th>
                            <th>Critère</th>
                            <th>Note</th>
                        </tr>
                    </thead>
                    <tbody>
                        {results.scoreEntries.map((entry) => (
                            <tr key={entry.id}>
                                <td>{entry.juryName}</td>
                                <td>{entry.team}</td>
                                <td>{entry.candidate}</td>
                                <td>{entry.section}</td>
                                <td>{entry.criterion}</td>
                                <td>{Number(entry.score).toFixed(2)}</td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>
        </div>
    );
};

export default Dashboard;
